/**
 * Steps pointing at the parts of a page (`design/components/tour.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/tour.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { Component, DestroyRef, ViewEncapsulation, inject, input, output } from '@angular/core'

import * as zag from '@zag-js/dialog'

import {
  MEMBER_PROVIDERS,
  Portal,
  Ref,
  Spread,
  agentMember,
  cell,
  classes,
  derived,
  elementRef,
  focusPlace,
  focusReturnTarget,
  mergeParts,
  mountEffect,
  normalizeProps,
  revealTourTarget,
  setup,
  tourPlacement,
  tourTarget,
  tourTargetRect,
  tourViewport,
  uniqueId,
  useDirection,
  useMachine,
  useMember,
  watchEffect,
} from '@polymorph/angular'
import { usePresence } from '@polymorph/angular/motion'
import styles from '@polymorph/recipes/overlays/tour.module.css'
import { Button, type ButtonProps } from '../controls/Button'

export interface TourStep {
  /** The step's key, unique in the tour. */
  id: string
  /** The `name` of the `Tour.Target` the step points at. Without one, the step is drawn centred. */
  target?: string
  title: string
  /** A sentence or two about the target, as text. */
  body: string
  /** The side of the target the panel opens on, when it fits there. */
  side?: 'top' | 'right' | 'bottom' | 'left'
}

export interface TourMessages {
  next: string
  previous: string
  /** The last step's forward control, which ends the tour. */
  done: string
  /** The close control's accessible name. */
  close: string
  /** The position line, counting from 1: "Step 2 of 5". */
  position: (position: number, count: number) => string
}

export type TourEnd = 'finished' | 'dismissed'

/** Steps pointing at the parts of a page: the inputs it takes, by the React member's prop names. */
export interface TourProps {
  defaultOpen?: boolean
  defaultStep?: number
  messages?: TourMessages
  open?: boolean
  /**
   * The current step's index, clamped to the steps.
   */
  step?: number
  steps: readonly TourStep[]
}

/** Steps pointing at the parts of a page. */
@Component({
  selector: 'pm-tour',
  encapsulation: ViewEncapsulation.None,
  host: { style: 'display: contents' },
  providers: [...MEMBER_PROVIDERS],
  imports: [Portal, Ref, Spread, Button],
  // prettier-ignore
  template: `<ng-template pmPortal>@if (e1()) {<!-- scrim -->
<div
[pmSpread]="e2()"
[pmRef]="scrim"
></div>}
@if (e3()) {<div
[pmSpread]="e4()"
[pmRef]="positioner"
><!-- panel -->
<div
[pmSpread]="e5()"
[pmRef]="panel"
><!-- title -->
<h2
[pmSpread]="e6()"
>{{ e7() }}</h2>
<!-- description -->
<div
[pmSpread]="e8()"
><!-- body -->
<p
[attr.class]="e9()"
>{{ e10() }}</p>
<!-- position -->
<p
[attr.class]="e11()"
data-tour-part="position"
>{{ e12() }}</p></div>
<!-- actions -->
<div
[attr.class]="e13()"
data-tour-part="actions"
>@if (e14()) {<pm-button
variant="outline"
tone="neutral"
size="sm"
[label]="e15()"
(click)="h1()"
></pm-button>}
<pm-button
size="sm"
[label]="e16()"
(click)="h2()"
></pm-button></div>
<!-- close -->
<div
[attr.class]="e17()"
data-tour-part="close"
><pm-button
variant="ghost"
tone="neutral"
size="sm"
[iconOnly]="e18()"
icon="close"
[label]="e19()"
(click)="h3()"
></pm-button></div></div></div>}</ng-template>`,
})
export class Tour {
  readonly defaultOpen = input<TourProps['defaultOpen']>(undefined)
  readonly defaultStep = input<TourProps['defaultStep']>(undefined)
  readonly messages = input<Exclude<TourProps['messages'], undefined>, TourProps['messages']>(
    (() => ({
      next: 'Next',
      previous: 'Previous',
      done: 'Done',
      close: 'Close',
      position: (position: number, count: number) => `Step ${position} of ${count}`,
    }))(),
    {
      transform: (value: TourProps['messages']) =>
        value === undefined
          ? (() => ({
              next: 'Next',
              previous: 'Previous',
              done: 'Done',
              close: 'Close',
              position: (position: number, count: number) => `Step ${position} of ${count}`,
            }))()
          : value,
    },
  )
  readonly open = input<TourProps['open']>(undefined)
  /**
   * The current step's index, clamped to the steps.
   */
  readonly step = input<TourProps['step']>(undefined)
  readonly steps = input.required<TourProps['steps']>()
  /**
   * Called when the reader ends the tour, with why. A tour never opens itself, so its end is the
   * one change it reports. The member stores nothing: the application records that the tour was
   * seen.
   */
  readonly onEnd = output<TourEnd>({ alias: 'end' })
  readonly onStepChange = output<number>({ alias: 'stepChange' })
  protected readonly $ = useMember({
    events: ['end', 'stepChange'],
    props: {
      defaultOpen: () => this.defaultOpen(),
      defaultStep: () => this.defaultStep(),
      messages: () => this.messages(),
      open: () => this.open(),
      step: () => this.step(),
      steps: () => this.steps(),
    },
  })
  protected readonly $p = this.$.props
  protected readonly uid = uniqueId()
  protected readonly uncontrolledStep = cell(() => this.$p.defaultStep ?? 0)
  protected readonly ending = cell(() => null as 'finished' | 'dismissed' | null)
  protected readonly returnTo = cell(() => null as ReturnType<typeof focusPlace>)
  protected readonly geometry = cell(
    () =>
      null as {
        x: number
        y: number
        placement: 'top' | 'right' | 'bottom' | 'left' | 'center'
        hole: { x: number; y: number; width: number; height: number } | null
      } | null,
  )
  protected readonly panel = elementRef<HTMLElement>()
  protected readonly positioner = elementRef<HTMLElement>()
  protected readonly scrim = elementRef<HTMLElement>()
  protected readonly count = derived(() => this.$p.steps.length)
  protected readonly index = derived(() =>
    Math.min(
      Math.max(this.$p.step ?? this.uncontrolledStep.value, 0),
      Math.max(this.count.value - 1, 0),
    ),
  )
  protected readonly current = derived(() => this.$p.steps[this.index.value])
  protected readonly first = derived(() => this.index.value === 0)
  protected readonly last = derived(() => this.index.value === this.count.value - 1)
  protected readonly drawnAt = derived(() => this.geometry.value?.placement ?? 'center')
  protected readonly cutOut = derived(() => this.geometry.value?.hole ?? null)
  protected readonly go = derived(() => (next: number): void => {
    this.uncontrolledStep.value = next
    this.$.emit(this.onStepChange, 'onStepChange', next)
  })
  protected readonly closed = derived(() => (open: boolean): void => {
    if (open) return
    const reason = this.ending.value ?? 'dismissed'
    this.ending.value = null
    this.$.emit(this.onEnd, 'onEnd', reason)
  })
  protected readonly place = derived(() => (): void => {
    if (this.positioner.value == null || this.current.value === undefined) return
    const rect = tourTargetRect(tourTarget(this.current.value.target))
    const next = {
      ...tourPlacement(
        rect,
        { width: this.positioner.value.offsetWidth, height: this.positioner.value.offsetHeight },
        tourViewport(),
        this.current.value.side,
      ),
      hole: rect,
    }
    if (JSON.stringify(next) !== JSON.stringify(this.geometry.value)) this.geometry.value = next
  })
  protected readonly follow = derived(() => (): (() => void) => {
    const again = (): void => this.place.value()
    window.addEventListener('resize', again)
    document.addEventListener('scroll', again, { capture: true, passive: true })
    return () => {
      window.removeEventListener('resize', again)
      document.removeEventListener('scroll', again, { capture: true })
    }
  })
  protected readonly documentDirection = useDirection()
  protected readonly service: { readonly value: zag.Service } = setup(() =>
    useMachine(
      zag.machine,
      () =>
        ({
          id: this.uid,
          dir: this.documentDirection(),
          open: this.$p.open === undefined ? undefined : this.$p.open && this.count.value > 0,
          defaultOpen: this.$p.defaultOpen === true && this.count.value > 0,
          preventScroll: false,
          closeOnInteractOutside: false,
          initialFocusEl: () => this.panel.value,
          finalFocusEl: () => focusReturnTarget(this.returnTo.value, [this.panel.value]),
          onOpenChange: (details) => {
            this.closed.value(details.open)
          },
        }) as Partial<zag.Props>,
    ),
  )
  protected readonly api: { readonly value: ReturnType<typeof zag.connect> } = derived(() =>
    zag.connect(this.service.value, normalizeProps),
  )
  protected readonly end = derived(() => (reason: 'finished' | 'dismissed'): void => {
    this.ending.value = reason
    this.api.value.setOpen(false)
  })
  protected readonly show = derived(() => (): void => {
    if (!this.api.value.open || this.current.value === undefined) return
    revealTourTarget(tourTarget(this.current.value.target))
    this.place.value()
    requestAnimationFrame(() => this.place.value())
  })
  protected readonly scrimPresent = setup(() =>
    usePresence(
      () => this.api.value.open && this.current.value !== undefined,
      () => this.scrim.value,
      'dialog.scrim',
    ),
  )
  protected readonly panelPresent = setup(() =>
    usePresence(
      () => this.api.value.open && this.current.value !== undefined,
      () => this.panel.value,
      'popover.panel',
      () => ({
        side: this.drawnAt.value === 'center' ? undefined : this.drawnAt.value,
        align: 'center',
      }),
    ),
  )
  private release3: (() => void) | undefined
  private release4: (() => void) | undefined
  private release6: (() => void) | undefined

  constructor() {
    watchEffect(
      () => this.api.value.open,
      () => this.effect1(),
      true,
    )
    watchEffect(
      () => [this.api.value.open, this.index.value],
      () => this.effect2(),
      true,
    )
    inject(DestroyRef).onDestroy(() => this.release3?.())
    watchEffect(
      () => this.api.value.open,
      () => this.effect3(),
      true,
    )
    inject(DestroyRef).onDestroy(() => this.release4?.())
    watchEffect(
      () => this.api.value.open,
      () => this.effect4(),
      true,
    )
    watchEffect(
      () => this.index.value,
      () => this.effect5(),
      false,
    )
    inject(DestroyRef).onDestroy(() => this.release6?.())
    mountEffect(() => this.effect6())
  }

  protected e1() {
    return this.scrimPresent.value()
  }

  protected e2() {
    if (!this.scrimPresent.value()) return undefined as never
    return mergeParts(this.api.value.getBackdropProps(), {
      class: classes(
        this.cutOut.value !== null ? styles.spotlight : undefined,
        this.cutOut.value === null ? styles.scrim : undefined,
      ),
      style: {
        '--pm-tour-hole-x': this.cutOut.value === null ? undefined : `${this.cutOut.value.x}px`,
        '--pm-tour-hole-y': this.cutOut.value === null ? undefined : `${this.cutOut.value.y}px`,
        '--pm-tour-hole-width':
          this.cutOut.value === null ? undefined : `${this.cutOut.value.width}px`,
        '--pm-tour-hole-height':
          this.cutOut.value === null ? undefined : `${this.cutOut.value.height}px`,
      },
      hidden: undefined,
      'aria-hidden': 'true',
      'data-tour-part': 'scrim',
    })
  }

  protected e3() {
    return this.panelPresent.value()
  }

  protected e4() {
    if (!this.panelPresent.value()) return undefined as never
    return mergeParts(this.api.value.getPositionerProps(), {
      class: styles.positioner,
      style: {
        '--pm-tour-x': `${this.geometry.value?.x ?? 0}px`,
        '--pm-tour-y': `${this.geometry.value?.y ?? 0}px`,
      },
      'data-placement': this.drawnAt.value,
    })
  }

  protected e5() {
    if (!this.panelPresent.value()) return undefined as never
    return mergeParts(this.api.value.getContentProps(), {
      class: styles.panel,
      hidden: undefined,
      'data-step': this.current.value?.id,
      'data-member': 'tour',
    })
  }

  protected e6() {
    if (!this.panelPresent.value()) return undefined as never
    return mergeParts(this.api.value.getTitleProps(), { class: styles.title })
  }

  protected e7() {
    if (!this.panelPresent.value()) return undefined as never
    return this.current.value?.title
  }

  protected e8() {
    if (!this.panelPresent.value()) return undefined as never
    return mergeParts(this.api.value.getDescriptionProps(), { class: styles.description })
  }

  protected e9() {
    if (!this.panelPresent.value()) return undefined as never
    return styles.body
  }

  protected e10() {
    if (!this.panelPresent.value()) return undefined as never
    return this.current.value?.body
  }

  protected e11() {
    if (!this.panelPresent.value()) return undefined as never
    return styles.position
  }

  protected e12() {
    if (!this.panelPresent.value()) return undefined as never
    return this.$p.messages.position(this.index.value + 1, this.count.value)
  }

  protected e13() {
    if (!this.panelPresent.value()) return undefined as never
    return styles.actions
  }

  protected e14() {
    if (!this.panelPresent.value()) return undefined as never
    return !this.first.value
  }

  protected e15(): ButtonProps['label'] {
    if (!this.panelPresent.value()) return undefined as never
    if (this.first.value) return undefined as never
    return this.$p.messages.previous
  }

  protected h1(): void {
    if (!this.panelPresent.value()) return
    if (this.first.value) return
    this.go.value(this.index.value - 1)
  }

  protected e16(): ButtonProps['label'] {
    if (!this.panelPresent.value()) return undefined as never
    return this.last.value ? this.$p.messages.done : this.$p.messages.next
  }

  protected h2(): void {
    if (!this.panelPresent.value()) return
    void (this.last.value ? this.end.value('finished') : this.go.value(this.index.value + 1))
  }

  protected e17() {
    if (!this.panelPresent.value()) return undefined as never
    return styles.close
  }

  protected e18(): ButtonProps['iconOnly'] {
    if (!this.panelPresent.value()) return undefined as never
    return true
  }

  protected e19(): ButtonProps['label'] {
    if (!this.panelPresent.value()) return undefined as never
    return this.$p.messages.close
  }

  protected h3(): void {
    if (!this.panelPresent.value()) return
    this.end.value('dismissed')
  }

  private effect1(): void {
    void (this.api.value.open && (this.returnTo.value = focusPlace(document.activeElement)))
  }

  private effect2(): void {
    this.show.value()
  }

  private effect3(): void {
    this.release3?.()
    const run = () => {
      this.place.value()
    }
    const resize = typeof ResizeObserver === 'undefined' ? undefined : new ResizeObserver(run)
    for (const element of [this.positioner.value]) if (element) resize?.observe(element)
    this.release3 = () => {
      resize?.disconnect()
    }
    run()
  }

  private effect4(): void {
    this.release4?.()
    const ran = this.follow.value()
    this.release4 = () => {
      ran()
    }
  }

  private effect5(): void {
    void (this.api.value.open && this.panel.value?.focus())
  }

  private effect6(): void {
    this.release6?.()
    const ran = agentMember({
      member: 'Tour',
      element: () => this.panel.value,
      state: () => ({
        open: this.api.value.open,
        step: this.index.value,
        steps: this.$p.steps.map((each) => ({ id: each.id, title: each.title, body: each.body })),
      }),
      actions: {
        next: () =>
          (() => {
            if (!this.api.value.open) throw new Error('The tour is not open.')
            if (this.last.value)
              throw new Error('On the last step, an agent ends a tour with dismiss.')
            this.go.value(this.index.value + 1)
          })(),
        previous: () =>
          (() => {
            if (!this.api.value.open) throw new Error('The tour is not open.')
            if (this.first.value) throw new Error('This is the first step.')
            this.go.value(this.index.value - 1)
          })(),
        dismiss: () => this.api.value.open && this.end.value('dismissed'),
      },
      withholds: () => this.panel.value,
    })
    this.release6 = () => {
      ran()
    }
  }
}
